(function(root){
  const App=root.DormRepairApp, Data=root.DormRepairData;
  if(!App||!Data)return;
  const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const cancelable=order=>['待派单','待接单','维修中','已中断','返工中'].includes(order.status);
  const queryId=()=>new URLSearchParams(location.search).get('id');
  const statusTone=status=>status==='已完成'?'green':status==='待接单'||status==='待确认'?'amber':'red';
  const statusTags=order=>`<span class="tag ${statusTone(order.status)}">${esc(order.status)}</span>${order.flags.map(flag=>`<span class="tag red">${esc(flag)}</span>`).join('')}`;
  const person=(state,id)=>state.workers.find(worker=>worker.id===id)?.name||'待分配';
  function timeline(order){return App.ui.timeline(order);}
  function formHtml(){const state=App.getState(),user=App.currentUser(state),options=App.getLocationOptions();return `<form class="form" id="repair-modal-form"><div class="grid two"><div class="field"><label class="required" for="modal-campus">校区</label><select class="select" id="modal-campus" name="campus"><option value="">请选择校区</option>${options.campuses.map(name=>`<option>${esc(name)}</option>`).join('')}</select></div><div class="field"><label class="required" for="modal-area">区域</label><select class="select" id="modal-area" name="area" disabled><option value="">请先选择校区</option></select></div><div class="field"><label class="required" for="modal-building">楼栋</label><select class="select" id="modal-building" name="building" disabled><option value="">请先选择区域</option></select></div><div class="field"><label class="required" for="modal-room">房间</label><select class="select" id="modal-room" name="room" disabled><option value="">请先选择楼栋</option></select></div></div><div class="field"><label for="modal-detail">具体位置</label><input class="input" id="modal-detail" name="detail" placeholder="例如：卫生间洗手池下方"></div><div class="field"><label class="required" for="modal-fault">故障类型</label><select class="select" id="modal-fault" name="faultType">${state.settings.faultTypes.map(type=>`<option>${esc(type)}</option>`).join('')}</select></div><div class="field"><label class="required" for="modal-description">问题描述</label><textarea class="textarea" id="modal-description" name="description" placeholder="请描述故障表现和发生时间"></textarea></div><div class="field"><label for="modal-photo">现场图片（可选）</label><input class="input" id="modal-photo" type="file" accept="image/*" multiple><small class="hint">图片仅在本机预览，不会上传。</small></div><div class="grid two"><div class="field"><label class="required" for="modal-contact">联系人</label><input class="input" id="modal-contact" name="contact" value="${esc(user?.name||'')}"></div><div class="field"><label class="required" for="modal-phone">联系方式</label><input class="input" id="modal-phone" name="phone" value="${esc(user?.phone||'')}"></div></div><div id="repair-modal-error" class="error" role="alert"></div></form>`;}
  function bindLocationCascade(dialog){const campus=dialog.querySelector('#modal-campus'),area=dialog.querySelector('#modal-area'),building=dialog.querySelector('#modal-building'),room=dialog.querySelector('#modal-room');const fill=(select,placeholder,items)=>{select.innerHTML=`<option value="">${placeholder}</option>${items.map(name=>`<option>${esc(name)}</option>`).join('')}`;select.disabled=!items.length;};campus.onchange=()=>{const options=App.getLocationOptions(campus.value);fill(area,campus.value?'请选择区域':'请先选择校区',options.areas);fill(building,'请先选择区域',[]);fill(room,'请先选择楼栋',[]);};area.onchange=()=>{const options=App.getLocationOptions(campus.value,area.value);fill(building,area.value?'请选择楼栋':'请先选择区域',options.buildings);fill(room,'请先选择楼栋',[]);};building.onchange=()=>{const options=App.getLocationOptions(campus.value,area.value,building.value);fill(room,building.value?'请选择房间':'请先选择楼栋',options.rooms);};}
  function openRepair(){const dialog=App.ui.modal({title:'提交报修',content:formHtml(),actions:[{label:'取消',onClick:wrap=>wrap.remove()},{label:'提交报修',className:'primary',onClick:wrap=>submitRepair(wrap)}]});bindLocationCascade(dialog);dialog.querySelector('#modal-campus')?.focus();}
  function submitRepair(wrap,force=false){const form=wrap.querySelector('#repair-modal-form'),input=Object.fromEntries(new FormData(form));const result=App.actions.createOrder({...input,force});if(!result.ok&&result.data?.reason==='duplicate'){wrap.remove();App.ui.modal({title:'发现相似未完成工单',content:`<div class="notice red">当前位置存在相似工单 <strong>${esc(result.data.orderId)}</strong>。你可以先查看，也可以继续提交。</div>`,actions:[{label:'返回修改',onClick:item=>{item.remove();openRepair()}},{label:'查看已有工单',onClick:()=>location.href=`student-order-detail.html?id=${result.data.orderId}`},{label:'仍然提交',className:'primary',onClick:item=>{item.remove();const forced=App.actions.createOrder({...input,force:true});if(forced.ok)location.href=`student-order-detail.html?id=${forced.data.id}`}}]});return;}if(!result.ok){wrap.querySelector('#repair-modal-error').textContent=result.message;return;}wrap.remove();App.ui.toast(result.message);setTimeout(()=>location.href=`student-order-detail.html?id=${result.data.id}`,350);}
  function askCancel(order){App.ui.modal({title:'取消工单',content:`<div class="notice red">取消后工单将停止后续维修流程，操作会记录在维修轨迹中。</div><div class="field" style="margin-top:14px"><label class="required" for="cancel-reason">取消原因</label><textarea class="textarea" id="cancel-reason" placeholder="例如：报修位置填写错误"></textarea><div id="cancel-error" class="error"></div></div>`,actions:[{label:'暂不取消',onClick:wrap=>wrap.remove()},{label:'确认取消',className:'danger',onClick:wrap=>{const result=App.actions.cancelOrder(order.id,wrap.querySelector('#cancel-reason').value);if(!result.ok){wrap.querySelector('#cancel-error').textContent=result.message;return;}wrap.remove();App.ui.toast(result.message);setTimeout(()=>location.reload(),350)}}]});}
  function orderCard(order,mine){return `<article class="card hover student-order-card clickable-order" data-status="${esc(order.status)}" tabindex="0" role="link" aria-label="查看工单 ${esc(order.id)} ${esc(order.title)}" data-order-detail="${esc(App.getOrderDetailUrl('student',order.id))}"><div class="order-card"><div><div class="order-id">${order.id}</div><div class="order-title">${esc(order.title)}</div><div class="meta"><span>${esc(order.location.building)} ${esc(order.location.room)}</span><span>${esc(order.faultType)}</span><span>${esc(order.createdAt)}</span></div><div style="margin-top:10px">${statusTags(order)}</div></div>${mine&&cancelable(order)?`<div class="order-actions"><button class="btn danger small" data-cancel="${order.id}">取消工单</button></div>`:''}</div></article>`;}
  function shell(page,title,subtitle,body){document.getElementById('app').innerHTML=App.ui.shell('student',page+'.html',title,subtitle,body);const nav=document.querySelector('.bottom-nav');if(nav)nav.innerHTML='<a class="'+(page==='student-home'?'active':'')+'" href="student-home.html">首页</a><a class="'+(page==='student-orders'?'active':'')+'" href="student-orders.html">我的工单</a>';document.querySelector('[data-logout]')?.addEventListener('click',()=>{App.logout();location.href='login.html'});document.querySelector('[data-reset]')?.addEventListener('click',()=>{App.resetState();location.reload()});}
  function bindCards(orders){App.ui.bindDetailRows();document.querySelectorAll('[data-cancel]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();askCancel(orders.find(order=>order.id===button.dataset.cancel))}));}
  function renderHome(){const state=App.getState(),user=App.currentUser(state),mine=state.orders.filter(order=>order.studentId===user.id),active=mine.filter(order=>!['待确认','已完成','已取消'].includes(order.status)),current=active[0];const hero=current?`<section class="hero"><div><span class="tag red">当前工单 · ${current.id}</span><h1>${esc(current.title)}</h1><p>${esc(current.location.campus)} ${esc(current.location.building)} ${esc(current.location.room)}，当前由 ${person(state,current.assigneeId)} 处理。</p><div class="track"><span class="done"></span><span class="done"></span><span class="now"></span><span></span><span></span></div><a class="btn outline" href="student-order-detail.html?id=${current.id}">查看进度</a></div><div class="hero-side"><div class="stat-value">${active.length}</div><div class="muted">本人进行中的报修</div></div></section>`:`<section class="card empty"><div class="empty-mark">✓</div><h2>当前没有进行中的报修</h2><p>如遇故障，可点击右上角“我要报修”。</p></section>`;shell('student-home','你好，'+user.name,'报修进度清楚，维修过程随时可查',`${hero}<section class="section"><div class="section-title"><div><h2>全校报修动态</h2><p class="muted">展示当前学校全部工单</p></div></div><div class="grid two">${state.orders.map(order=>orderCard(order,order.studentId===user.id)).join('')}</div></section>`);const head=document.querySelector('.page-head');const button=document.createElement('button');button.className='btn primary student-repair-trigger';button.textContent='我要报修';button.onclick=openRepair;head.appendChild(button);bindCards(state.orders);if(new URLSearchParams(location.search).get('repair')==='1')openRepair();}
  function renderOrders(){const state=App.getState(),user=App.currentUser(state),orders=state.orders.filter(order=>order.studentId===user.id);shell('student-orders','我的工单','查看本人发起的全部报修',`<div class="filters" aria-label="按处理状态筛选"><button class="filter active" data-filter="全部">全部</button>${Data.ORDER_STATUSES.map(status=>`<button class="filter" data-filter="${status}">${status}</button>`).join('')}</div><div class="grid" id="student-order-list">${orders.map(order=>orderCard(order,true)).join('')}</div><div class="empty hidden" id="student-filter-empty">当前状态下没有工单</div>`);document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(item=>item.classList.toggle('active',item===button));let visible=0;document.querySelectorAll('.student-order-card').forEach(card=>{const show=button.dataset.filter==='全部'||card.dataset.status===button.dataset.filter;card.classList.toggle('hidden',!show);if(show)visible++;});document.getElementById('student-filter-empty').classList.toggle('hidden',visible>0)});bindCards(orders);}
  function renderDetail(){const state=App.getState(),user=App.currentUser(state),order=state.orders.find(item=>item.id===queryId());if(!order){location.href='student-home.html';return;}const mine=order.studentId===user.id;shell('student-order-detail','工单详情',order.id,`<section class="card"><div class="section-title"><div><h2>${esc(order.title)}</h2><div>${statusTags(order)}</div></div>${mine&&cancelable(order)?`<button class="btn danger" data-cancel="${order.id}">取消工单</button>`:''}</div><div class="detail-list"><div class="detail-item"><small>故障位置</small><strong>${esc(Object.values(order.location).join(' '))}</strong></div><div class="detail-item"><small>报修时间</small><strong>${esc(order.createdAt)}</strong></div><div class="detail-item"><small>完成期限</small><strong>${esc(order.completeDeadline||'接单后生成')}</strong></div><div class="detail-item"><small>当前负责人</small><strong>${esc(person(state,order.assigneeId))}</strong></div></div><p>${esc(order.description)}</p></section><section class="card section"><div class="section-title"><h2>维修轨迹</h2><span class="muted">共 ${order.transitions.length} 个节点</span></div>${timeline(order)}</section>${mine&&order.status==='待确认'?`<section class="card section"><h2>等待你的确认</h2><p class="muted">请检查现场后确认完成或申请返工。</p><a class="btn primary" href="student-order-review.html?id=${order.id}">验收维修结果</a></section>`:''}`);bindCards([order]);}
  function render(page){if(!App.requireRole('student')){location.href='login.html';return;}if(page==='student-repair-create'){location.replace('student-home.html?repair=1');return;}if(page==='student-home')renderHome();else if(page==='student-orders')renderOrders();else if(page==='student-order-detail')renderDetail();}
  root.DormRepairStudentUI={render,openRepair,cancelable};
})(globalThis);
